/* Panneau chauffant infrarouge (photo détourée d'un panneau en feutre gris à trois volets) sur prise connectée :
   en chauffe, voyants rouges allumés sur la télécommande, les volets rougeoient doucement et des ondes de chaleur infrarouge montent devant le panneau.
   Éteint : voyants éteints, panneau froid. Le cordon est redessiné (la photo l'a perdu au détourage). */
const IR_PANEL_IMG = "data:image/webp;base64,";
SVG.infrared_panel = () => `
<defs>${DEFS}
<radialGradient id="ID-irpg" cx=".5" cy=".55" r=".7"><stop offset="0" stop-color="#ff7a2a" stop-opacity=".95"/><stop offset=".6" stop-color="#e8341c" stop-opacity=".55"/><stop offset="1" stop-color="#b3150f" stop-opacity=".2"/></radialGradient>
<filter id="ID-irpb" x="-30%" y="-30%" width="160%" height="160%"><feGaussianBlur stdDeviation="3"/></filter></defs>
<ellipse cx="55" cy="98" rx="52" ry="3.6" fill="url(#ID-shadow)"/>
<g transform="translate(2 4) scale(.158)">
  <image href="${IR_PANEL_IMG}" width="621" height="583"/>
  <g class="ip-glow" style="mix-blend-mode:screen">
    <path d="M80 14L358 10L360 432L92 480Z" fill="url(#ID-irpg)"/>
    <path d="M364 10L566 10Q582 14 582 40L584 440Q584 452 568 452L364 432Z" fill="url(#ID-irpg)"/>
  </g>
  <path d="M592 283C650 290 652 330 646 372C642 400 650 424 664 438" fill="none" stroke="#9aa0a6" stroke-width="13" stroke-linecap="round"/>
  <path d="M592 283C650 290 652 330 646 372C642 400 650 424 664 438" fill="none" stroke="#eceef0" stroke-width="9" stroke-linecap="round"/>
  <circle class="ip-led" cx="552" cy="205" r="5.5"/><circle class="ip-led" cx="552" cy="239" r="5.5"/>
  <circle class="ip-led ip-halo" cx="552" cy="205" r="14" filter="url(#ID-irpb)"/><circle class="ip-led ip-halo" cx="552" cy="239" r="14" filter="url(#ID-irpb)"/>
  <g class="ip-waves">${[140, 235, 330, 470].map((x, i) => `<path d="M${x} 470q-14 -22 0 -44t0 -44t0 -44" style="animation-delay:${(-i * 0.55).toFixed(2)}s"/>`).join("")}</g>
</g>`;
